"""Opt-in F3 gate. No measurement; all generated bytes live in .scratch-fix.

Create .scratch-fix, then run::

    B5_GAMMA_STALE_GATE=1 TMPDIR="$PWD/.scratch-fix" PYTHONDONTWRITEBYTECODE=1 \
        /opt/homebrew/bin/python3.13 -m unittest tests.test_harvest_b5_trigger_scope_gamma_gate

The gate uses the real verdict lock/core/row/basis/log/publication path and
the unmodified real G3 subprocess. Member evaluations and calibration
candidate discovery are synthetic. The ledger, binding, and terminal pin
are produced/loaded by their real implementations. Outcome injection is
confined to the separate G3 response-mapping test.
"""
from __future__ import annotations

import base64
import contextlib
import io
import json
import os
import subprocess
import sys
import tempfile
import unittest
import zlib
from dataclasses import replace
from pathlib import Path
from types import SimpleNamespace
from unittest import mock

from joulewise import calibration_bracketing as br
from joulewise import calibration_ledger as cl
from joulewise import whole_window as ww
from joulewise.b5 import harvest as h
from scripts import run_campaign as rc
from tests import test_harvest_b5_trigger_scope as scope_tests
from tests import test_harvest_b5_window as wt
from tests import test_run_campaign as campaign_tests

REPO = Path(__file__).resolve().parents[1]
SCRATCH = REPO / '.scratch-fix'
REHEARSALS = Path('/Users/edr/night-archive/gate-prune/rehearsal-real')
MANIFEST_ID = 'am-' + 'a' * 64


@unittest.skipUnless(os.environ.get('B5_GAMMA_STALE_GATE') == '1', 'opt-in F3 GAMMA stale gate')
class GammaStaleGate(unittest.TestCase):
    def setUp(self):
        self.assertTrue(SCRATCH.is_dir(), 'create .scratch-fix before running the opt-in gate')
        self.assertEqual(Path(tempfile.gettempdir()).resolve(), SCRATCH.resolve())
        self.directory = tempfile.TemporaryDirectory(prefix='gamma-f3-', dir=SCRATCH)
        self.addCleanup(self.directory.cleanup)
        self.root = Path(self.directory.name)
        self.evaluator = scope_tests.WindowEvidenceTests()
        self.evaluator.setUp()

    def test_rehearsal_shape_census(self):
        shapes = []
        for name in ('alpha-1', 'gamma-1', 'gamma-2', 'corpus18-20261009T1816Z',
                     'corpus18-20261009T1944Z', 'corpus18-20261009T1949Z'):
            base = REHEARSALS / name
            plan = h.read_json(base / 'custody/night_plan.json')
            pack = Path(h._plan_value(plan, 'pack_root'))
            self.assertIn(base, pack.parents)
            gamma = (pack / 'analysis_manifest_v3.json').is_file()
            claim = Path(h._plan_value(plan, 'claim_runs_root'))
            self.assertIn(base, claim.parents)
            shapes.append((name, gamma, (claim / 'bracket-binding.json').is_file(),
                           (claim / 'whole-window-verdict.json').is_file()))
        self.assertEqual([name for name, gamma, *_ in shapes if gamma], ['gamma-1', 'gamma-2'])
        for name, gamma, binding, verdict in shapes:
            print('rehearsal_shape', name, 'GAMMA' if gamma else 'OTHER',
                  'binding_present' if binding else 'binding_absent',
                  'verdict_present' if verdict else 'verdict_absent')
        sealed = REHEARSALS / 'corpus18-20261009T1949Z/measurement'
        for relative in ('scripts/run_campaign.py', 'scripts/check_window_provenance.py'):
            self.assertEqual(wt.sha(REPO / relative), wt.sha(sealed / relative), relative)
        print('sealed_program_identity PASS writer checker')

    def snapshot(self, window):
        cutoff = self.evaluator.artifact['ledger_cutoff']
        snapshot = cl.load_calibration_ledger_snapshot(
            window.ledger, window.pin, require_committed_pin=False, verify_custody=False,
            mode='read_replay', baseline_sequence=cutoff['sequence'],
            baseline_digest=cutoff['head_digest'])
        self.assertEqual(snapshot.refusal_reasons, ())
        return snapshot

    def physical_pin(self, window):
        rows = [json.loads(line) for line in window.ledger.read_bytes().splitlines()]
        wt.put(window.pin, {'sequence': len(rows), 'head_digest': rows[-1]['receipt_digest'],
                            'ledger_schema': cl.LEDGER_SCHEMA})

    def session(self, window, session_id, *, systematic=False):
        epoch = self.evaluator.artifact['identity_epoch']
        t1 = self.evaluator.helper.bindings
        slots = {}
        runs_root = self.root / 'other-runs' if systematic else window.claim
        for slot in ('pre', 'post'):
            capture = runs_root / 'instrument_validation' / f'{session_id}-{slot}'
            if not capture.is_dir():
                (capture / 'raw').mkdir(parents=True)
                (capture / 'raw/powermetrics.plist').write_bytes(b'synthetic capture')
                (capture / 'events.jsonl').write_text('{}\n')
                wt.put(capture / 'manifest.json', {'synthetic': session_id, 'slot': slot})
                wt.put(capture / 'instrument_evidence.json', {'synthetic': session_id, 'slot': slot})
            slots[slot] = {'attempt_id': f'{session_id}-{slot}', 'custody_locator': str(capture),
                           'identity_epoch': epoch, 't1_bindings': t1}
        cl.append_bracket_session_receipt(
            window.ledger, session_id=session_id, window_id=wt.PLAN_ID if not systematic else 'other-window',
            plan_id=wt.PLAN_ID, plan_sha256=wt.sha(window.pack / 'calibration_plan.json'),
            evidence_root_id=wt.EVIDENCE_ROOT_ID, runs_root=runs_root,
            slots=slots, head_pin_path=window.pin, require_committed_pin=False)
        for slot in ('pre', 'post'):
            capture = Path(slots[slot]['custody_locator'])
            cl.finalize_bracket_session_slot(
                window.ledger, session_id=session_id, slot=slot,
                disposition='systematic-invalid' if systematic else 'valid',
                custody_locator=str(capture), artifact_sha256=cl.artifact_hashes(capture),
                identity_epoch=epoch, t1_bindings=t1,
                capture_wall_time_s='99.0' if slot == 'pre' else '111.0',
                exact_bound_lexeme_s='0.044' if systematic else '0.028' if slot == 'pre' else '0.03050')
            if systematic:
                cl.abort_bracket_session(window.ledger, session_id=session_id, reason='synthetic pre above screen')
                break
        self.physical_pin(window)

    def evaluation(self, window, snapshot, binding, *, scope='sealed'):
        # Discovery is the synthetic boundary: the evaluator itself and its
        # exact census/binding/trigger decisions are real, over the real ledger.
        candidates = []
        for observation in snapshot.observations:
            if (observation.is_historical_import or observation.disposition != 'valid'
                    or br._capture_pipeline_refusal_for_observation(observation) is not None
                    or br._is_derivation_kind_observation(observation, snapshot)):
                continue
            candidates.append(br.CalibrationCandidate(
                relative_path=observation.custody_locator,
                manifest_sha256=observation.artifact_sha256['manifest.json'],
                evidence_sha256=observation.artifact_sha256['instrument_evidence.json'],
                protocol_id=br.PROTOCOL_ID, capture_wall_time_s=float(observation.capture_wall_time_s),
                b_fiducial_s=observation.exact_bound_lexeme_s, bindings=observation.t1_bindings,
                attempt_id=observation.attempt_id, content_id=observation.content_id,
                ledger_receipt_digest=observation.receipt_digest,
                **{field: getattr(observation, field) for field in (
                    'bracket_session_id', 'bracket_slot', 'bracket_window_id', 'bracket_plan_id',
                    'bracket_plan_sha256', 'bracket_evidence_root_id', 'bracket_runs_root')}))
        return br.evaluate_calibration_bracket(
            candidates, window_start_s=100.0, window_end_s=110.0,
            bindings=self.evaluator.helper.bindings, policy=self.evaluator.helper.policy,
            ledger_snapshot=snapshot, bracket_binding=binding, bracket_window_id=wt.PLAN_ID,
            bracket_plan_id=wt.PLAN_ID, bracket_plan_sha256=wt.sha(window.pack / 'calibration_plan.json'),
            bracket_evidence_root_id=wt.EVIDENCE_ROOT_ID, bracket_runs_root=window.claim,
            trigger_scope=scope)

    def gamma_manifest(self, window):
        order = window.pack / 'f3-root-order.json'
        wt.put(order, {
            'manifest_id': 'f3-order', 'executed_order': [{'run_id': row[0]} for row in wt.MEMBERS]})
        wt.put(window.pack / 'analysis_manifest_v3.json', {
            'manifest_id': MANIFEST_ID, 'stage_manifests': [{'subcampaign_id': 'f3-science'}],
            'root_order_manifest': {
                'path': order.name, 'sha256': wt.sha(order), 'manifest_id': 'f3-order'}})
        manifest = {'schema_version': 'joulewise.campaign_provenance.v1',
                    'config_dir': str(window.pack / 'f3-science'),
                    'analysis_manifest_id': MANIFEST_ID,
                    'analysis_manifest_sha256': wt.sha(window.pack / 'analysis_manifest_v3.json'),
                    'campaign_policy': {'sha256': wt.sha(window.measurement / wt.POLICY)},
                    'members': [{'config': row[0] + '.json', 'run_id': row[0], 'execution': 'invoked',
                                 'bundle_ids': [row[0]], 'role': row[1]} for row in wt.MEMBERS]}
        for member, position in zip(manifest['members'], ('start', 'end')):
            member.update(role=rc.NEG8_REFERENCE_ROLE, sentinel_position=position,
                          scientific_config_sha256='b' * 64, canonical_neg8_workload=True)
        wt.put(window.claim / 'campaign_manifests/f3-science.json', manifest)

    def write_verdict(self, window, snapshot, binding):
        # Use clean synthetic member/idle/reference inputs without replacing
        # the core evaluator, row builder, basis builder, log or publication.
        helper = campaign_tests.IdleAdmissionCoreVerdictTests()
        helper.root = self.root / 'writer-members'
        helper.root.mkdir(exist_ok=True)
        evaluations = []
        for row in wt.MEMBERS:
            member = helper._member(row[0], records=campaign_tests._clean_idle_records(count=30),
                                    gross_energy_j=8.0)
            evaluations.append(replace(member, bundle_path=window.claim / row[0]))
        # Two synthetic reference evaluations feed the real NEG-8 core;
        # physical basis members remain the unchanged helper window roster.
        for index, position in enumerate(('start', 'end')):
            member = helper._member(wt.MEMBERS[index][0], records=campaign_tests._clean_idle_records(count=30),
                                    gross_energy_j=8.0, neg8_position=position)
            evaluations[index] = replace(member, bundle_path=window.claim / member.bundle_id,
                                         scientific_config_sha256='b' * 64, canonical_neg8_workload=True)
        bound_path = self.root / 'writer-bound.json'
        if not bound_path.is_file():
            wt.put(bound_path, helper._drift_bound())
        output = window.claim / 'whole-window-verdict.json'
        output.unlink(missing_ok=True)
        (window.claim / 'campaign_log.jsonl').unlink(missing_ok=True)
        args = rc.parse_args(['--whole-window-verdict', '--runs-dir', str(window.claim),
            '--campaign-policy', str(window.measurement / wt.POLICY),
            '--neg8-drift-bound', str(bound_path), '--calibration-ledger', str(window.ledger),
            '--head-pin', str(window.pin), '--bracket-binding', str(window.claim / 'bracket-binding.json'),
            '--whole-window-verdict-output', str(output)])
        scopes = []
        def evaluate(*_args, **kwargs):
            scopes.append(kwargs.get('trigger_scope', 'sealed'))
            self.assertIs(kwargs['ledger_snapshot'], snapshot)
            return self.evaluation(window, snapshot, binding)
        with contextlib.ExitStack() as stack:
            stack.enter_context(mock.patch.object(rc, '_whole_window_member_evaluations', return_value=evaluations))
            stack.enter_context(mock.patch.object(rc, '_load_idle_rich_telemetry',
                                                 return_value=campaign_tests._clean_idle_records(count=30)))
            stack.enter_context(mock.patch.object(rc, '_neg8_reference_scientific_config_sha256',
                                                 return_value='b' * 64))
            stack.enter_context(mock.patch.object(rc, '_load_calibration_snapshot_for_evaluation', return_value=snapshot))
            stack.enter_context(mock.patch.object(rc, 'calibration_bracket_for_bundles', side_effect=evaluate))
            # Launch receipts are not a hardware fixture. The fresh basis has
            # a synthetic lineage; the stale basis must omit it without a seam.
            lineage = {'schema_version': 'f3.synthetic.launch', 'plan_id': wt.PLAN_ID}
            stack.enter_context(mock.patch.object(ww, '_authenticated_bundle_launch_lineage_set', return_value=lineage))
            stack.enter_context(mock.patch.object(ww, '_authenticate_whole_window_launch_sources', return_value=lineage))
            stdout = io.StringIO()
            stack.enter_context(contextlib.redirect_stdout(stdout))
            exit_code = rc.run_whole_window_verdict(args)
        self.assertEqual(scopes, ['sealed'])
        row = h.read_json(output)
        self.assertIsInstance(row['member_failures'], list)
        logs = [json.loads(line) for line in (window.claim / 'campaign_log.jsonl').read_bytes().splitlines()]
        self.assertEqual([value for value in logs if value.get('record_type') == row['record_type']], [row])
        self.assertIsNotNone(ww._validated_evaluation_basis(row, window.claim))
        return row, exit_code, stdout.getvalue().splitlines()[-1].strip()

    def harvest_arm(self, window, snapshot, binding, label):
        window.archive = self.root / ('archive-' + label)
        def evaluate(*_args, **kwargs):
            self.assertEqual(kwargs['trigger_scope'], 'window_evidence')
            return self.evaluation(window, snapshot, binding, scope='window_evidence')
        seams = h.Seams(group_alive=lambda _: False, exclusions_compute=wt.EXCLUSIONS,
                        python=sys.executable, boot_session_uuid=lambda: 'F3-SYNTHETIC')
        self.assertIs(seams.runner, subprocess.run)
        with mock.patch.object(br, 'calibration_bracket_for_bundles', side_effect=evaluate):
            record = window.harvest(seams=seams)
        report_path = window.archive / 'withheld/g3-report.json'
        self.assertTrue(report_path.is_file(), 'the real checker must publish its report')
        report = h.read_json(report_path)
        self.assertEqual(report['exit_code'], 1)
        statuses = [(row['id'], row['status']) for row in report['assertions']]
        self.assertEqual([status for assertion, status in statuses if assertion == 'F5-2'], ['FAIL'],
                         next(row['detail'] for row in report['assertions'] if row['id'] == 'S11-A2'))
        self.assertIn(('NR14-LAYOUT', 'PASS'), statuses)
        # An authenticated roster means F5-2 runs its own consumption path,
        # rather than reporting a startup error or prerequisite skip.
        self.assertIn(('S11-A1', 'PASS'), statuses)
        f52 = next(row for row in report['assertions'] if row['id'] == 'F5-2')
        self.assertIn('verdict is not an independently clean pass', f52['detail'])
        self.assertEqual(record['calibration_bracket']['status'], 'passed')
        self.assertEqual(record['faults'], [])
        flags = window.flags()
        checker_tail = (window.archive / 'withheld/transcripts/g3.txt').read_text().splitlines()[-1]
        self.assertEqual(checker_tail, 'SUMMARY pass=5 skip=1 fail=4')
        print('real_checker', label, 'exit', report['exit_code'], 'report_present',
              'assertions', json.dumps(statuses))
        print('real_checker_last_line', label, checker_tail)
        return record, flags

    def test_real_writer_real_checker_stale_and_control(self):
        window = wt.Window(self.root / 'window', prefix_ledger=True, catalog_overrides=wt.WindowTestCase.ISOLATE)
        plan = h.read_json(window.plan_path)
        plan['t0_epoch_s'] = h.ERRATUM_3_ADMITTED_AT_EPOCH_S + 1
        wt.put(window.plan_path, plan)
        self.gamma_manifest(window)
        window.ledger.write_bytes(zlib.decompress(base64.b85decode(wt.PREFIX.read_bytes())))
        self.physical_pin(window)
        self.session(window, wt.SESSION_ID)
        snapshots = []
        for stale, label in ((False, 'control'), (True, 'stale')):
            if stale:
                # The target session must remain the physical terminal head,
                # as in the stale production state. Rebuild only the scratch
                # ledger through its writer, inserting the other session first.
                window.ledger.write_bytes(zlib.decompress(base64.b85decode(wt.PREFIX.read_bytes())))
                self.physical_pin(window)
                self.session(window, 'f3-other-session', systematic=True)
                self.session(window, wt.SESSION_ID)
            snapshot = self.snapshot(window)
            binding = br.build_calibration_bracket_binding(snapshot, session_id=wt.SESSION_ID,
                window_id=wt.PLAN_ID, plan_id=wt.PLAN_ID,
                plan_sha256=wt.sha(window.pack / 'calibration_plan.json'),
                evidence_root_id=wt.EVIDENCE_ROOT_ID, runs_root=window.claim)
            (window.claim / 'bracket-binding.json').write_bytes(cl.canonical_json_bytes(binding) + b'\n')
            bracket, reasons = self.evaluation(window, snapshot, binding)
            self.assertEqual(bracket['status'], 'failed' if stale else 'passed', ','.join(reasons))
            self.assertEqual(reasons, ('calibration_acceptance_bound_stale',) if stale else ())
            row, writer_exit, writer_tail = self.write_verdict(window, snapshot, binding)
            self.assertEqual(row['idle_admission_core']['instrument_calibration_bracket'], bracket)
            self.assertEqual(writer_exit, 1 if stale else 0)
            self.assertEqual(row['status'], 'failed' if stale else 'passed')
            self.assertEqual(row['idle_admission_core']['conditions'],
                             ['calibration_acceptance_bound_stale'] if stale else [])
            self.assertEqual(writer_tail, 'condition: calibration_acceptance_bound_stale' if stale else 'decision: passed')
            if stale:
                self.assertEqual(writer_exit, 1)
                basis = row['evaluation_basis']
                self.assertIsNone(basis['calibration_bracket_set']['pre'])
                self.assertIsNone(basis['calibration_bracket_set']['post'])
                self.assertNotIn('launch_lineage', basis)
                self.assertIsNone(bracket['pre'])
                self.assertIsNone(bracket['post'])
            self.assertEqual(row['member_failures'], [])
            record, flags = self.harvest_arm(window, snapshot, binding, label)
            print('sealed_writer', label, 'exit', writer_exit, 'status', row['status'],
                  'member_failures', len(row['member_failures']))
            print('sealed_writer_last_line', label, writer_tail)
            print('writer_conditions', label, json.dumps(row['idle_admission_core']['conditions']))
            print('writer_member_failure_codes', label,
                  json.dumps(sorted({failure['reason_code'] for failure in row['member_failures']})))
            print('exclude_window_reasons', label, json.dumps(record['exclude_window_reasons']))
            snapshots.append((record, flags, row))
        control, stale = snapshots
        self.assertEqual(control[0]['exclude_window_reasons'], stale[0]['exclude_window_reasons'])
        catalog = h.Catalog.load(REPO / 'configs/campaigns/v5_claim_25g83/flag_catalog.json')
        removing = set(stale[0]['exclude_window_reasons'])
        self.assertEqual(removing, {'calibration.capture_battery_unmeasured', 'neg8.bound_not_derived'})
        self.assertNotIn('whole_window.member_failures_unreadable', removing)
        def payloads(flags, code):
            return sorted(json.dumps({'observed': flag['observed'], 'expected': flag['expected']}, sort_keys=True)
                          .replace(str(self.root / 'archive-control'), '<archive>')
                          .replace(str(self.root / 'archive-stale'), '<archive>')
                          for flag in flags if flag['code'] == code)
        for code in sorted(removing):
            self.assertEqual(catalog.effect(code), 'EXCLUDE_WINDOW')
            self.assertEqual(payloads(control[1], code), payloads(stale[1], code), code)
            print('removal_payload', code, 'EQUAL', 'count', len(payloads(stale[1], code)))
        changed = sorted(code for code in {f['code'] for f in control[1] + stale[1]}
                         if payloads(control[1], code) != payloads(stale[1], code))
        added = sorted({f['code'] for f in stale[1]} - {f['code'] for f in control[1]})
        self.assertEqual(added, ['whole_window.not_passed'])
        self.assertEqual(changed, ['whole_window.not_passed'])
        for code in changed:
            self.assertEqual(catalog.effect(code), 'DISCLOSE', code)
        print('stale_added_codes', json.dumps(added))
        print('stale_changed_payload_codes', json.dumps(changed))
        print('F3_real_paths PASS')

    def test_checker_outcome_mapping(self):
        window = wt.Window(self.root / 'mapping', prefix_ledger=True)
        wt.put(window.pack / 'analysis_manifest_v3.json', {})
        wt.put(window.claim / 'bracket-binding.json', {})
        wt.put(window.claim / 'whole-window-verdict.json', {})
        catalog = h.Catalog.load(REPO / 'configs/campaigns/v5_claim_25g83/flag_catalog.json')
        cases = []
        for exit_code in (0, 1, 2, -9, None):
            for f52 in ('PASS', 'FAIL', 'SKIP', None, 'CONFLICT'):
                for other_fail in (False, True):
                    rows = [] if f52 is None else [{'id': 'F5-2', 'status': f52}]
                    if f52 == 'CONFLICT':
                        rows = [{'id': 'F5-2', 'status': 'PASS'}, {'id': 'F5-2', 'status': 'FAIL'}]
                    if other_fail:
                        rows.append({'id': 'S11-A2', 'status': 'FAIL'})
                    expected = ({'g3.recompute_failed'} if exit_code not in (0, 1) or f52 != 'PASS' else set())
                    if other_fail:
                        expected.add('g3.assertion_failed')
                    cases.append((f'report-{exit_code}-{f52}-{int(other_fail)}', exit_code,
                                  {'assertions': rows}, '', None, expected))
        for kind, payload in (('absent', None), ('malformed', '{'), ('nonobject', []),
                              ('rows_absent', {}), ('rows_wrong_type', {'assertions': {}})):
            for stdout, extra in (('', set()), ('FAIL S11-A2 injected\n', {'g3.assertion_failed'})):
                cases.append((kind + ('-stdout' if stdout else ''), 0, payload, stdout, None,
                              {'g3.recompute_failed'} | extra))
        for exception in (FileNotFoundError('injected spawn failure'),
                          subprocess.TimeoutExpired('injected checker', 1)):
            cases.append((type(exception).__name__, None, None, '', exception,
                          {'g3.recompute_failed', 'records.collector_failed'}))
        cases.extend([
            ('duplicate_pass', 0, {'assertions': [{'id': 'F5-2', 'status': 'PASS'}] * 2}, '', None, set()),
            ('report_ignores_stdout', 0, {'assertions': [{'id': 'F5-2', 'status': 'PASS'}]},
             'FAIL S11-A2 injected\n', None, set()),
            ('invalid_rows_filtered', 0, {'assertions': [None, 'FAIL']}, '', None, {'g3.recompute_failed'}),
            ('stdout_f52_fail_only', 1, None, 'FAIL F5-2 injected\n', None, {'g3.recompute_failed'}),
        ])
        for index, (name, exit_code, payload, stdout, exception, expected) in enumerate(cases):
            with self.subTest(case=name):
                archive = self.root / f'mapping-output-{index}'
                def runner(argv, **kwargs):
                    self.assertEqual(kwargs, {'capture_output': True, 'text': True, 'check': False, 'timeout': 3600})
                    self.assertIn('--full-window', argv)
                    if exception is not None:
                        raise exception
                    report = Path(argv[argv.index('--report-json') + 1])
                    if isinstance(payload, str):
                        report.write_text(payload)
                    elif payload is not None:
                        wt.put(report, payload)
                    return SimpleNamespace(returncode=exit_code, stdout=stdout, stderr='')
                run = h._Harvest(h.resolve_inputs(window.plan_path), archive,
                    h.Seams(runner=runner, harvest_checkout=lambda: {}), prepare_desk=False, run_g3=True)
                run.derived.mkdir(parents=True)
                run.withheld.mkdir(parents=True)
                wt.put(run.derived / 'terminal-pin.json', {})
                wt.put(run.derived / 'terminal-boundary.json', {})
                run.g3()
                codes = {flag['code'] for flag in run.flags.records}
                self.assertEqual(codes, expected)
                for code in codes:
                    self.assertEqual(catalog.effect(code), 'DISCLOSE')
        print('checker_outcome_mapping PASS cases', len(cases),
              'codes g3.assertion_failed g3.recompute_failed records.collector_failed', 'effects DISCLOSE')

    def test_g3_preconditions(self):
        window = wt.Window(self.root / 'preconditions', prefix_ledger=True)
        manifest = window.pack / 'analysis_manifest_v3.json'
        wt.put(manifest, {})
        for index, (label, skip, expected) in enumerate((
                ('skipped', True, 'g3.recompute_failed'),
                ('desk_outputs_absent', False, 'g3.recompute_failed'),
                ('not_applicable', False, 'g3.not_applicable'))):
            if label == 'not_applicable':
                manifest.unlink()
            runner = mock.Mock(side_effect=AssertionError('no subprocess permitted in this precondition'))
            run = h._Harvest(h.resolve_inputs(window.plan_path), self.root / f'precondition-{index}',
                h.Seams(runner=runner, harvest_checkout=lambda: {}), prepare_desk=False, run_g3=True)
            run.g3(skipped=skip)
            runner.assert_not_called()
            self.assertEqual({flag['code'] for flag in run.flags.records}, {expected})
            self.assertEqual(run.catalog.effect(expected), 'DISCLOSE')
        print('checker_preconditions PASS cases 3 effects DISCLOSE')


def tearDownModule():
    # The imported window helper caches its source bundles outside individual
    # TemporaryDirectory scopes. Remove that gate-owned scratch cache too.
    if os.environ.get('B5_GAMMA_STALE_GATE') == '1':
        wt.tearDownModule()


if __name__ == '__main__':
    unittest.main()
